void handle_nonopt(char *opt, gchar ** hostname, long int *p)
{
	static int nonopt = 0;

	switch (nonopt) {
	case 0:
		*hostname = g_strdup(opt);
		nonopt++;
		break;
	case 1:
		*p = (strtol(opt, NULL, 0));
		if (*p == LONG_MIN || *p == LONG_MAX) {
