static int tree_depth(off_t size)
{
	int depth = 1;
	/* number of blocks addressable by a tree of this depth */
	off_t blocks = TREEDIRSIZE;  // depth 1: TREEDIRSIZE files
	off_t need = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	if (need < 1) need = 1;
	while (blocks < need) {
		depth++;
		if (blocks > need / TREEDIRSIZE)
			break;  /* blocks * TREEDIRSIZE >= need, this depth is enough */
		blocks *= TREEDIRSIZE;
	}
	return depth;
}
