```c
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex)
{
	char path[PATH_MAX];
	off_t ppos;
	int fd;

	strncpy(path, name, sizeof path);
	path[sizeof path - 1] = '\0';
	construct_path(path, sizeof path, size, pos, &ppos);
	if (!path[0]) {
		errno = ENAMETOOLONG;
		return -1;
	}

	fd = open(path, mode, 0600);
	if (fd >= 0 || errno != ENOENT || !(mode & O_CREAT))
		return fd;

	pthread_mutex_lock(mutex);
	fd = open(path, mode, 0600);
	if (fd < 0 && errno == ENOENT) {
		char dir[PATH_MAX];
		char *sep;

		strncpy(dir, path, sizeof dir);
		dir[sizeof dir - 1] = '\0';
		sep = strrchr(dir, '/');
		if (sep != NULL && sep != dir) {
			*sep = '\0';
			mkdir_path(dir);
		}
		fd = open(path, mode, 0600);
	}
	pthread_mutex_unlock(mutex);

	return fd;
}
```

