/*
 * Tree files support.
 *
 * An export with the treefiles option is stored as a tree of small
 * block files below a directory carrying the name of the export. The
 * export is divided into TREEPAGESIZE-byte blocks; every directory in
 * the tree holds at most TREEDIRSIZE entries (files or subdirectories).
 * A block is therefore addressed by the digits of its block number in
 * base TREEDIRSIZE, most significant digit first: every digit but the
 * last one names a subdirectory (TREEXXXX), the last one names the
 * block file itself (FILEXXXX), where XXXX is the digit zero-padded to
 * four positions. The tree is always exactly as deep as needed to hold
 * filesize bytes.
 *
 * Block files are created on demand when written to; a block without a
 * backing file reads as all zeroes. See nbd-server(5).
 */
#include "lfs.h"
#include "config.h"
#include "treefiles.h"

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#include "nbd-debug.h"

/**
 * Compute the depth of the tree needed to hold a device of the given
 * size, i.e. the number of digits needed to express all block numbers
 * in base TREEDIRSIZE.
 *
 * @param size total size of the exported device
 * @return the depth of the tree, at least 1
 **/
static int tree_depth(off_t size) {
	int depth = 1;
	off_t need = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	off_t blocks = TREEDIRSIZE;

	if (need < 1)
		need = 1;
	while (blocks < need) {
		depth++;
		if (blocks > need / TREEDIRSIZE)
			break;
		blocks *= TREEDIRSIZE;
	}

	return depth;
}

/**
 * Construct the path to the block file holding a given position of
 * the exported device. The full path is appended to the export name
 * already present in name.
 *
 * @param name buffer holding the name of the export; the path of the
 * block file is appended to it. If the buffer is too small, it is
 * emptied so that callers fail cleanly.
 * @param lenmax total size of the name buffer
 * @param size total size of the exported device
 * @param pos position in the exported device
 * @param ppos if not NULL, receives the position within the block file
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	off_t block = pos / TREEPAGESIZE;
	int depth = tree_depth(size);
	int written = strlen(name);
	int level;

	for (level = depth - 1; level >= 0; level--) {
		off_t div = 1;
		int idx;
		int l;
		int n;

		for (l = 0; l < level; l++)
			div *= TREEDIRSIZE;
		idx = (block / div) % TREEDIRSIZE;
		n = snprintf(name + written, lenmax - written, "/%s%04d",
			     level > 0 ? "TREE" : "FILE", idx);
		if (n < 0 || n >= lenmax - written) {
			name[0] = '\0';
			break;
		}
		written += n;
	}
	if (ppos != NULL)
		*ppos = pos % TREEPAGESIZE;
}

/**
 * Recursively create all directories in a path, like mkdir -p.
 * Errors are ignored; they will resurface when the path is used.
 *
 * @param path the directory path to create; modified temporarily
 **/
void mkdir_path(char *path) {
	char *p;

	for (p = strchr(path, '/'); p != NULL; p = strchr(p + 1, '/')) {
		if (p != path) {
			*p = '\0';
			mkdir(path, 0700);
			*p = '/';
		}
	}
	mkdir(path, 0700);
}

/**
 * Open the block file holding a given position of the exported device,
 * creating the file (and any missing directories) on demand if the
 * mode allows it.
 *
 * @param name the name of the export, i.e. of the root of the tree
 * @param mode open flags for the block file
 * @param size total size of the exported device
 * @param pos position in the exported device
 * @param mutex serializes creation of files and directories
 * @return a file descriptor, or -1 on error
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[PATH_MAX];
	off_t ppos;
	int fd;

	strncpy(path, name, sizeof(path));
	path[sizeof(path) - 1] = '\0';
	construct_path(path, sizeof(path), size, pos, &ppos);
	if (!path[0]) {
		errno = ENAMETOOLONG;
		return -1;
	}

	fd = open(path, mode, 0600);
	if (fd >= 0 || errno != ENOENT || !(mode & O_CREAT))
		return fd;

	pthread_mutex_lock(mutex);
	fd = open(path, mode, 0600);
	if (fd < 0 && errno == ENOENT) {
		char dir[PATH_MAX];
		char *sep;

		strncpy(dir, path, sizeof(dir));
		dir[sizeof(dir) - 1] = '\0';
		sep = strrchr(dir, '/');
		if (sep != NULL && sep != dir) {
			*sep = '\0';
			mkdir_path(dir);
		}
		fd = open(path, mode, 0600);
	}
	pthread_mutex_unlock(mutex);
	DEBUG("Opened treefile %s\n", path);

	return fd;
}

/**
 * Delete the block file holding a given position of the exported
 * device, if it exists.
 *
 * @param name the name of the export, i.e. of the root of the tree
 * @param size total size of the exported device
 * @param pos position in the exported device
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char path[PATH_MAX];
	off_t ppos;

	strncpy(path, name, sizeof(path));
	path[sizeof(path) - 1] = '\0';
	construct_path(path, sizeof(path), size, pos, &ppos);
	if (!path[0])
		return;
	if (unlink(path) < 0 && errno != ENOENT) {
		DEBUG("Could not delete treefile %s: %s\n", path, strerror(errno));
	}
}

