arguments.new_string:
/**
 * Call rawexpread repeatedly until all data has been read.
 * @return 0 on success, nonzero on failure
 **/
int rawexpread_fully(READ_CTX *ctx, CLIENT *client) {
	ssize_t ret=0;

	char *buf;

	while(ctx->current_len > 0) {
		buf = find_read_buf(ctx);
		if((ret = rawexpread((off_t)ctx->req->from + (off_t)ctx->current_offset, buf, ctx->current_len, client)) <= 0) {
			break;
		}
		confirm_read(client, ctx, ret);
		ctx->current_offset += ret;
		ctx->current_len -= ret;
	}
	return (ret < 0 || ctx->current_len != 0);
}

/**
 * Read from a treefiles export. The request is split up per block
 * file; blocks that have no backing file read as all zeroes.
 *
 * @param ctx The read context we're serving for
 * @param client The client we're serving for
 * @return 0 on success, nonzero on failure
 **/
int treeexpread(READ_CTX *ctx, CLIENT *client) {
	while(ctx->current_len > 0) {
		off_t a = (off_t)ctx->req->from + (off_t)ctx->current_offset;
		off_t ppos = a % TREEPAGESIZE;
		size_t chunk = TREEPAGESIZE - ppos;
		char *buf;
		int fd;

		if(chunk > ctx->current_len)
			chunk = ctx->current_len;
		buf = find_read_buf(ctx);
		fd = open_treefile(client->exportname, O_RDONLY,
				   client->exportsize, a,
				   &client->treefiles_mutex);
		if(fd >= 0) {
			ssize_t r = pread(fd, buf, chunk, ppos);
			close(fd);
			if(r < 0)
				return -1;
			/* the block file may be shorter than a full
			 * block; the remainder reads as zeroes */
			if((size_t)r < chunk)
				memset(buf + r, 0, chunk - r);
		} else {
			if(errno != ENOENT)
				return -1;
			memset(buf, 0, chunk);
		}
		DEBUG("(READ treefile at %llu len %u), ", (unsigned long long)a, (unsigned int)chunk);
		ctx->current_offset += chunk;
		ctx->current_len -= chunk;
		confirm_read(client, ctx, chunk);
	}
	return 0;
}

/**
 * Write to a treefiles export. The request is split up per block
 * file; block files and directories are created on demand.
 *
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param client The client we're serving for
 * @param fua Flag to indicate 'Force Unit Access'
 * @return 0 on success, nonzero on failure
 **/
int treeexpwrite(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	while(len > 0) {
		off_t ppos = a % TREEPAGESIZE;
		size_t chunk = TREEPAGESIZE - ppos;
		ssize_t w;
		int fd;

		if(chunk > len)
			chunk = len;
		fd = open_treefile(client->exportname, O_RDWR | O_CREAT,
				   client->exportsize, a,
				   &client->treefiles_mutex);
		if(fd < 0)
			return -1;
		DEBUG("(WRITE treefile at %llu len %u fua %d), ", (unsigned long long)a, (unsigned int)chunk, fua);
		w = pwrite(fd, buf, chunk, ppos);
		if(w == (ssize_t)chunk) {
			if(client->server->flags & F_SYNC) {
				fsync(fd);
			} else if(fua) {
				fdatasync(fd);
			}
		}
		close(fd);
		if(w != (ssize_t)chunk) {
			if(w >= 0)
				errno = EIO;
			return -1;
		}
		a += chunk;
		buf += chunk;
		len -= chunk;
	}
	return 0;
}

